window.HEIRLOOM = {"data":{"version":1,"categories":["Breakfast","Mains","Soups","Sides","Breads","Desserts","Drinks"],"recipes":[{"id":"blueberry-buttermilk-pancakes","title":"Blueberry Buttermilk Pancakes","category":"Breakfast","cuisine":"American","description":"Tall, tender buttermilk pancakes dotted with jammy blueberries. A slow Saturday morning on a plate.","prepMin":10,"cookMin":20,"serves":4,"difficulty":"Easy","ingredients":[{"text":"2 cups (250 g) all-purpose flour","header":false},{"text":"2 Tbsp sugar","header":false},{"text":"2 tsp baking powder","header":false},{"text":"1 tsp baking soda","header":false},{"text":"½ tsp salt","header":false},{"text":"2 cups buttermilk","header":false},{"text":"2 large eggs","header":false},{"text":"3 Tbsp unsalted butter, melted, plus more for the pan","header":false},{"text":"1 tsp vanilla extract","header":false},{"text":"1 cup fresh blueberries","header":false},{"text":"Maple syrup, to serve","header":false}],"steps":[{"lead":"Whisk the dry.","text":"In a large bowl, whisk together the flour, sugar, baking powder, baking soda and salt.","timer":0,"timerText":""},{"lead":"Whisk the wet.","text":"In a second bowl, whisk the buttermilk, eggs, melted butter and vanilla until smooth.","timer":0,"timerText":""},{"lead":"Combine gently.","text":"Pour the wet ingredients into the dry and fold with a spatula until just combined. A few lumps are good. Let the batter rest for 5 minutes.","timer":300,"timerText":"5 min"},{"lead":"Heat the griddle.","text":"Warm a griddle or large skillet over medium heat and brush it lightly with butter.","timer":0,"timerText":""},{"lead":"Cook the pancakes.","text":"Pour ¼ cup of batter per pancake and scatter a few blueberries on top. Cook 2–3 minutes, until bubbles form and the edges look set, then flip and cook 1–2 minutes more.","timer":120,"timerText":"2 min"},{"lead":"Serve warm.","text":"Keep finished pancakes in a 200°F oven while you cook the rest. Serve with a pat of butter and warm maple syrup.","timer":0,"timerText":""}],"kitchenNote":"Don't press the pancakes after flipping. Let them rise on their own. Frozen blueberries work too; add them straight from the freezer so they don't bleed.","accent":{"garnish":"berries","color":"#4A5BA8"},"image":"images/dishes/blueberry-buttermilk-pancakes.jpg","photo":"images/photos/farmhouse.png","tags":["vegetarian","brunch","family"],"prepText":"10 min","cookText":"20 min","totalText":"30 min","garnish":"images/garnish/berries.png","thumb":"images/dishes/blueberry-buttermilk-pancakes.jpg"},{"id":"huevos-rancheros","title":"Huevos Rancheros","category":"Breakfast","cuisine":"Mexican","description":"Crisp-edged fried eggs on warm corn tortillas with black beans and a smoky ranchero sauce. A ranch-hand breakfast worth waking up for.","prepMin":10,"cookMin":25,"serves":4,"difficulty":"Easy","ingredients":[{"text":"Ranchero sauce","header":true},{"text":"1 Tbsp vegetable oil","header":false},{"text":"½ white onion, chopped","header":false},{"text":"1 jalapeño, seeded and minced","header":false},{"text":"2 cloves garlic, minced","header":false},{"text":"½ tsp ground cumin","header":false},{"text":"1 can (14½ oz) fire-roasted diced tomatoes","header":false},{"text":"½ tsp salt","header":false},{"text":"Juice of ½ lime","header":false},{"text":"To serve","header":true},{"text":"8 corn tortillas (6-inch)","header":false},{"text":"2 Tbsp vegetable oil","header":false},{"text":"8 large eggs","header":false},{"text":"1 can (15 oz) black beans, drained and warmed","header":false},{"text":"1 ripe avocado, sliced","header":false},{"text":"½ cup crumbled queso fresco","header":false},{"text":"Fresh cilantro and lime wedges","header":false}],"steps":[{"lead":"Start the sauce.","text":"Heat the oil in a saucepan over medium heat. Cook the onion and jalapeño for 5 minutes, until soft. Add the garlic and cumin and stir for 30 seconds, until fragrant.","timer":300,"timerText":"5 min"},{"lead":"Simmer it down.","text":"Add the tomatoes and salt and simmer for 10 minutes, stirring now and then, until slightly thickened. Blend briefly if you like it smooth, stir in the lime juice and keep warm.","timer":600,"timerText":"10 min"},{"lead":"Warm the tortillas.","text":"Heat a skillet over medium-high heat and brush the tortillas lightly with oil. Fry each for about 30 seconds per side, until soft and blistered. Wrap in a clean towel.","timer":30,"timerText":"30 sec"},{"lead":"Fry the eggs.","text":"Lower the heat to medium and add the remaining oil. Crack in the eggs and fry for 3–4 minutes, until the whites are fully set and the edges are lacy but the yolks still run.","timer":180,"timerText":"3 min"},{"lead":"Build the plates.","text":"Overlap two tortillas on each plate, add a spoonful of black beans and top with two eggs. Ladle the warm sauce around the yolks.","timer":0,"timerText":""},{"lead":"Finish and serve.","text":"Scatter over the avocado, queso fresco and cilantro, and tuck a lime wedge on the side. Serve right away, while the tortillas are warm.","timer":0,"timerText":""}],"kitchenNote":"Make the sauce the night before; it only gets better. On busy mornings I crack the eggs straight into the simmering sauce, cover the pan, and call it breakfast.","accent":{"garnish":"lime","color":"#6FA23A"},"image":"images/dishes/huevos-rancheros.jpg","photo":"images/photos/hacienda.png","tags":["vegetarian","gluten-free","brunch","eggs"],"prepText":"10 min","cookText":"25 min","totalText":"35 min","garnish":"images/garnish/lime.png","thumb":"images/dishes/huevos-rancheros.jpg"},{"id":"argentine-beef-empanadas","title":"Argentine Beef Empanadas","category":"Mains","cuisine":"Argentine","description":"Flaky hand pies filled with cumin-spiced beef, sweet pepper, egg and olives, crimped by hand and baked until deep golden. Makes 12.","prepMin":120,"cookMin":45,"serves":6,"difficulty":"Hard","ingredients":[{"text":"Dough","header":true},{"text":"3 cups (375 g) all-purpose flour, plus more for rolling","header":false},{"text":"1 tsp salt","header":false},{"text":"½ cup (113 g) cold unsalted butter or lard, cubed","header":false},{"text":"1 large egg","header":false},{"text":"½ cup (120 ml) cold water, plus 1–2 Tbsp as needed","header":false},{"text":"Filling","header":true},{"text":"1 Tbsp olive oil","header":false},{"text":"1 large onion, finely diced","header":false},{"text":"1 red bell pepper, finely diced","header":false},{"text":"1 lb (450 g) ground beef (85% lean)","header":false},{"text":"2 tsp sweet paprika","header":false},{"text":"2 tsp ground cumin","header":false},{"text":"½ tsp crushed red pepper flakes","header":false},{"text":"1 tsp salt","header":false},{"text":"4 scallions, thinly sliced","header":false},{"text":"2 hard-boiled eggs, chopped","header":false},{"text":"¼ cup pitted green olives, chopped","header":false},{"text":"1 egg, beaten, for brushing","header":false}],"steps":[{"lead":"Make the dough.","text":"Whisk the flour and salt, then rub in the butter with your fingertips until it looks like coarse crumbs. Beat the egg with the water, stir it in, and add more water a spoonful at a time until the dough holds. Wrap and chill for 1 hour.","timer":3600,"timerText":"1 hr"},{"lead":"Soften the vegetables.","text":"Heat the oil in a large skillet over medium heat. Cook the onion and red pepper for 8–10 minutes, stirring now and then, until very soft and sweet.","timer":480,"timerText":"8 min"},{"lead":"Brown the beef.","text":"Raise the heat to medium-high, add the beef and cook for 6–8 minutes, breaking it up, until browned with no pink left (160°F). Stir in the paprika, cumin, pepper flakes and salt and cook for 1 minute.","timer":360,"timerText":"6 min"},{"lead":"Cool the filling.","text":"Stir in the scallions, spread the filling on a plate and chill for 30 minutes, until cold. Warm filling melts the dough and makes the empanadas leak.","timer":1800,"timerText":"30 min"},{"lead":"Roll and cut.","text":"Heat the oven to 400°F and line two baking sheets with parchment. Roll the dough out thin, about 3 mm (1/8 inch), and cut 12 rounds about 5 inches across, rerolling the scraps once.","timer":0,"timerText":""},{"lead":"Fill and crimp.","text":"Spoon 2 heaping Tbsp of filling onto each round and top with a little egg and olive. Brush the edge with water, fold into a half-moon and press to seal, then twist the edge into a rope or crimp it with a fork.","timer":0,"timerText":""},{"lead":"Bake.","text":"Set the empanadas on the sheets, brush with beaten egg and bake for 20–25 minutes, until deep golden. Rest for 5 minutes before serving; the filling is very hot.","timer":1200,"timerText":"20 min"}],"kitchenNote":"The twisted rope edge is called the repulgue and takes a few tries; a fork crimp seals just as well. Unbaked empanadas freeze beautifully. Bake from frozen, adding 5 minutes.","accent":{"garnish":"pepper","color":"#C0392B"},"image":"images/dishes/argentine-beef-empanadas.jpg","photo":"images/photos/hacienda.png","tags":["beef","baking","party","freezer-friendly"],"prepText":"2 hr","cookText":"45 min","totalText":"2 hr 45 min","garnish":"images/garnish/pepper.png","thumb":"images/dishes/argentine-beef-empanadas.jpg"},{"id":"pork-and-chive-dumplings","title":"Pork and Chive Dumplings","category":"Mains","cuisine":"Chinese","description":"Juicy pork and garlic-chive potstickers in hand-rolled wrappers, with crisp golden bottoms and a sharp black-vinegar dip.","prepMin":75,"cookMin":25,"serves":4,"difficulty":"Hard","ingredients":[{"text":"Wrappers","header":true},{"text":"2½ cups (320 g) all-purpose flour, plus more for dusting","header":false},{"text":"½ cup (120 ml) just-boiled water","header":false},{"text":"¼ cup (60 ml) cold water","header":false},{"text":"Filling","header":true},{"text":"1 lb (450 g) ground pork, not too lean","header":false},{"text":"1 cup garlic chives (or scallions), finely chopped","header":false},{"text":"1 Tbsp freshly grated ginger","header":false},{"text":"2 Tbsp soy sauce","header":false},{"text":"1 Tbsp Shaoxing wine (or dry sherry)","header":false},{"text":"1 tsp toasted sesame oil","header":false},{"text":"½ tsp sugar","header":false},{"text":"½ tsp salt","header":false},{"text":"¼ tsp ground white pepper","header":false},{"text":"3 Tbsp cold water","header":false},{"text":"2 Tbsp neutral oil, for frying","header":false},{"text":"Dipping sauce","header":true},{"text":"3 Tbsp Chinkiang black vinegar","header":false},{"text":"2 Tbsp soy sauce","header":false},{"text":"1 tsp chili oil","header":false},{"text":"1 tsp ginger, cut into fine threads","header":false}],"steps":[{"lead":"Make the dough.","text":"Stir the just-boiled water into the flour with chopsticks until shaggy, then add the cold water and knead for 5 minutes until smooth. Cover and rest for 30 minutes.","timer":1800,"timerText":"30 min"},{"lead":"Mix the filling.","text":"Combine the pork, ginger, soy sauce, wine, sesame oil, sugar, salt and pepper. Stir hard in one direction, adding the water a spoonful at a time, until sticky, about 2 minutes. Fold in the chives.","timer":120,"timerText":"2 min"},{"lead":"Roll the wrappers.","text":"Roll the dough into a log and cut 32 pieces. Flatten each and roll into a 3½-inch round, thinner at the edge than the middle. Keep the rest covered as you go.","timer":0,"timerText":""},{"lead":"Fold and pleat.","text":"Spoon a heaped teaspoon of filling into the centre, fold in half and pinch the top. Pleat one side toward the middle, pressing each pleat to the flat side. Set on a floured tray.","timer":0,"timerText":""},{"lead":"Sear the bottoms.","text":"Heat 1 Tbsp oil in a large nonstick skillet over medium-high heat. Arrange half the dumplings flat side down in a ring and fry for 2 minutes, until golden underneath.","timer":120,"timerText":"2 min"},{"lead":"Steam them through.","text":"Pour in 1/3 cup water and cover at once. Steam over medium heat for 6–7 minutes, until the wrappers turn translucent and the filling reaches 160°F.","timer":360,"timerText":"6 min"},{"lead":"Crisp and serve.","text":"Uncover and cook 1–2 minutes more, until the water is gone and the bottoms crackle. Repeat with the rest. Stir the dipping sauce together and serve hot.","timer":60,"timerText":"1 min"}],"kitchenNote":"Make a double batch and freeze them on a floured tray, then bag them. Cook straight from frozen, adding 2 minutes of steaming. A dumpling-folding party is the best kind.","accent":{"garnish":"scallion","color":"#5E8A2E"},"image":"images/dishes/pork-and-chive-dumplings.jpg","photo":"images/photos/teahouse.png","tags":["pork","dairy-free","weekend-project","freezer-friendly"],"prepText":"1 hr 15 min","cookText":"25 min","totalText":"1 hr 40 min","garnish":"images/garnish/scallion.png","thumb":"images/dishes/pork-and-chive-dumplings.jpg"},{"id":"tuscan-lemon-chicken-piccata","title":"Tuscan Lemon Chicken Piccata","category":"Mains","cuisine":"Italian","description":"Golden chicken cutlets in a bright lemon, garlic and caper sauce. Serve with roasted asparagus or a little angel hair pasta.","prepMin":10,"cookMin":20,"serves":4,"difficulty":"Easy","ingredients":[{"text":"4 boneless, skinless chicken breasts (about 1½ lb)","header":false},{"text":"½ cup all-purpose flour","header":false},{"text":"1 tsp salt","header":false},{"text":"½ tsp black pepper","header":false},{"text":"½ tsp Italian seasoning","header":false},{"text":"2 Tbsp olive oil","header":false},{"text":"2 Tbsp unsalted butter","header":false},{"text":"3 cloves garlic, minced","header":false},{"text":"¾ cup low-sodium chicken broth","header":false},{"text":"1/3 cup fresh lemon juice (about 2 lemons)","header":false},{"text":"2 Tbsp capers, drained","header":false},{"text":"Zest of 1 lemon (about 1 tsp)","header":false},{"text":"¼ cup fresh parsley, chopped, plus more to garnish","header":false}],"steps":[{"lead":"Prepare the chicken.","text":"Slice each breast in half horizontally to make 8 thin cutlets. Season both sides with the salt, pepper and Italian seasoning, then dredge lightly in flour, shaking off any excess.","timer":0,"timerText":""},{"lead":"Sear the chicken.","text":"Heat the olive oil in a large skillet over medium-high heat. Cook the cutlets in batches, 3–4 minutes per side, until golden and cooked through (165°F inside). Move to a plate and tent loosely with foil.","timer":180,"timerText":"3 min"},{"lead":"Make the sauce.","text":"Lower the heat to medium and melt the butter in the same skillet. Stir in the garlic and cook for about 30 seconds, just until fragrant.","timer":30,"timerText":"30 sec"},{"lead":"Add the brightness.","text":"Pour in the broth and lemon juice, scraping up the browned bits from the pan. Stir in the capers and lemon zest and simmer 3–4 minutes, until slightly reduced.","timer":180,"timerText":"3 min"},{"lead":"Bring it together.","text":"Return the chicken and any juices to the skillet and spoon the sauce over the top. Simmer for 2 minutes to warm through.","timer":120,"timerText":"2 min"},{"lead":"Serve.","text":"Scatter with parsley and a few extra lemon slices. Lovely with roasted asparagus, a green salad or angel hair pasta.","timer":0,"timerText":""}],"kitchenNote":"Squeeze the lemons fresh and add a little extra zest at the very end. Leftover sauce is wonderful tossed through a bowl of buttered pasta the next day.","accent":{"garnish":"lemon","color":"#E9B824"},"image":"images/dishes/tuscan-lemon-chicken-piccata.jpg","photo":"images/photos/villa.png","tags":["chicken","weeknight","citrus"],"prepText":"10 min","cookText":"20 min","totalText":"30 min","garnish":"images/garnish/lemon.png","thumb":"images/dishes/tuscan-lemon-chicken-piccata.jpg"},{"id":"turkish-red-lentil-soup","title":"Turkish Red Lentil Soup","category":"Soups","cuisine":"Turkish","description":"Mercimek çorbası: a silky, golden lentil soup finished with sizzling chili-mint oil and a squeeze of lemon.","prepMin":10,"cookMin":35,"serves":6,"difficulty":"Easy","ingredients":[{"text":"For the soup","header":true},{"text":"2 Tbsp olive oil","header":false},{"text":"1 large onion, chopped","header":false},{"text":"1 medium carrot, chopped","header":false},{"text":"2 cloves garlic, minced","header":false},{"text":"1 Tbsp tomato paste","header":false},{"text":"1 tsp ground cumin","header":false},{"text":"1 tsp sweet paprika","header":false},{"text":"1½ cups (300 g) red lentils, rinsed","header":false},{"text":"6 cups vegetable broth","header":false},{"text":"1 tsp salt, or to taste","header":false},{"text":"For the chili-mint oil","header":true},{"text":"3 Tbsp olive oil","header":false},{"text":"1 tsp Aleppo pepper, or ½ tsp red pepper flakes","header":false},{"text":"1 tsp dried mint","header":false},{"text":"Lemon wedges, to serve","header":false}],"steps":[{"lead":"Soften the vegetables.","text":"Warm the olive oil in a large pot over medium heat. Add the onion and carrot and cook 6–8 minutes, stirring now and then, until soft and sweet.","timer":360,"timerText":"6 min"},{"lead":"Bloom the spices.","text":"Stir in the garlic, tomato paste, cumin and paprika and cook for 1 minute, until the paste darkens and smells toasty.","timer":60,"timerText":"1 min"},{"lead":"Simmer.","text":"Add the lentils and broth and bring to a boil. Lower the heat, partly cover and simmer 20–25 minutes, until the lentils have completely collapsed.","timer":1200,"timerText":"20 min"},{"lead":"Blend until silky.","text":"Purée with an immersion blender until smooth. Thin with a splash of hot water if it is too thick, then season with salt.","timer":0,"timerText":""},{"lead":"Make the chili-mint oil.","text":"Warm the olive oil in a small pan until shimmering. Take it off the heat and stir in the Aleppo pepper and dried mint; it will sizzle and turn red.","timer":0,"timerText":""},{"lead":"Serve.","text":"Ladle the soup into bowls, swirl over the chili-mint oil and serve with lemon wedges for squeezing.","timer":0,"timerText":""}],"kitchenNote":"Don't skip the lemon. It wakes the whole bowl up. The soup thickens as it sits, so loosen leftovers with a little water when you reheat them.","accent":{"garnish":"chili","color":"#B8321E"},"image":"images/dishes/turkish-red-lentil-soup.jpg","photo":"images/photos/bazaar.png","tags":["vegan","gluten-free","budget"],"prepText":"10 min","cookText":"35 min","totalText":"45 min","garnish":"images/garnish/chili.png","thumb":"images/dishes/turkish-red-lentil-soup.jpg"},{"id":"west-african-peanut-soup","title":"West African Peanut Soup","category":"Soups","cuisine":"West African","description":"A silky, gently spiced soup of sweet potato, tomato and peanut, finished with tender greens. Hearty, warming and naturally vegan.","prepMin":15,"cookMin":40,"serves":6,"difficulty":"Easy","ingredients":[{"text":"2 Tbsp peanut or vegetable oil","header":false},{"text":"1 large onion, diced","header":false},{"text":"3 garlic cloves, minced","header":false},{"text":"1 Tbsp freshly grated ginger","header":false},{"text":"1 small Scotch bonnet or jalapeño, seeded and minced","header":false},{"text":"2 Tbsp tomato paste","header":false},{"text":"1 tsp ground coriander","header":false},{"text":"1 large sweet potato (about 1 lb), peeled and cut in ¾-inch cubes","header":false},{"text":"1 can (14½ oz) diced tomatoes","header":false},{"text":"5 cups (1.2 L) vegetable broth (gluten-free if needed)","header":false},{"text":"1 tsp salt, plus more to taste","header":false},{"text":"½ cup (130 g) natural unsweetened peanut butter","header":false},{"text":"4 cups chopped kale or spinach (about 3 oz)","header":false},{"text":"¼ cup roasted peanuts, chopped, and fresh cilantro, to serve","header":false}],"steps":[{"lead":"Soften the aromatics.","text":"Heat the oil in a large pot over medium heat. Cook the onion for 5–6 minutes, until soft and golden at the edges, then stir in the garlic, ginger and chili for 1 minute more.","timer":300,"timerText":"5 min"},{"lead":"Toast the paste.","text":"Stir in the tomato paste and coriander and cook for 2 minutes, stirring, until the paste darkens to a deep brick red.","timer":120,"timerText":"2 min"},{"lead":"Simmer the soup.","text":"Add the sweet potato, tomatoes, broth and salt. Bring to a boil, then cover, lower the heat and simmer for 15–20 minutes, until the sweet potato is tender.","timer":900,"timerText":"15 min"},{"lead":"Stir in the peanut butter.","text":"Whisk the peanut butter with a ladle of the hot broth until smooth, then stir it into the pot. Mash a few chunks of sweet potato against the side of the pot to thicken the soup.","timer":0,"timerText":""},{"lead":"Wilt the greens.","text":"Add the kale and simmer for 5 minutes, until tender and bright. Taste, and add more salt or a little more chili if you like.","timer":300,"timerText":"5 min"},{"lead":"Serve.","text":"Ladle into warm bowls and scatter with the chopped peanuts and cilantro. Lovely with rice or crusty bread on the side.","timer":0,"timerText":""}],"kitchenNote":"Use a peanut butter made with nothing but peanuts and salt. The soup thickens as it stands, so loosen leftovers with a splash of broth when you warm them.","accent":{"garnish":"peanut","color":"#B5651D"},"image":"images/dishes/west-african-peanut-soup.jpg","photo":"images/photos/village.png","tags":["vegan","gluten-free","one-pot","budget"],"prepText":"15 min","cookText":"40 min","totalText":"55 min","garnish":"images/garnish/peanut.png","thumb":"images/dishes/west-african-peanut-soup.jpg"},{"id":"korean-cucumber-salad","title":"Korean Cucumber Salad","category":"Sides","cuisine":"Korean","description":"Oi muchim: crisp salted cucumbers tossed with garlic, chili flakes, sesame and a splash of vinegar. Ready in minutes, no stove needed.","prepMin":25,"cookMin":0,"serves":4,"difficulty":"Easy","ingredients":[{"text":"2 English cucumbers or 6 Persian cucumbers (about 1½ lb)","header":false},{"text":"1 tsp kosher salt","header":false},{"text":"2 scallions, thinly sliced","header":false},{"text":"2 garlic cloves, finely grated","header":false},{"text":"1–2 tsp gochugaru (Korean chili flakes)","header":false},{"text":"1 Tbsp rice vinegar","header":false},{"text":"2 tsp tamari (or soy sauce if gluten isn't a concern)","header":false},{"text":"1 tsp sugar","header":false},{"text":"1 tsp toasted sesame oil","header":false},{"text":"1 tsp toasted sesame seeds","header":false}],"steps":[{"lead":"Slice the cucumbers.","text":"Trim the ends. Halve any wide cucumbers lengthwise, then slice them about ¼ inch thick on a slight diagonal.","timer":0,"timerText":""},{"lead":"Salt and drain.","text":"Toss the slices with the salt in a bowl and set aside for 15 minutes. Squeeze them gently by the handful and pour off the liquid; this keeps the salad crisp.","timer":900,"timerText":"15 min"},{"lead":"Mix the dressing.","text":"In a large bowl, stir together the garlic, gochugaru, vinegar, tamari, sugar and sesame oil until the sugar dissolves.","timer":0,"timerText":""},{"lead":"Toss and serve.","text":"Add the cucumbers and scallions and toss with your hands so every slice is coated. Sprinkle with sesame seeds and serve within the hour, cold or at room temperature.","timer":0,"timerText":""}],"kitchenNote":"Gochugaru is fruity more than fiery, so taste and add another pinch if you like. Eat it the day it's made, while the cucumbers still snap.","accent":{"garnish":"cucumber","color":"#4E8A3A"},"image":"images/dishes/korean-cucumber-salad.jpg","photo":"images/photos/teahouse.png","tags":["vegan","gluten-free","no-cook","quick"],"prepText":"25 min","cookText":"None","totalText":"25 min","garnish":"images/garnish/cucumber.png","thumb":"images/dishes/korean-cucumber-salad.jpg"},{"id":"provencal-ratatouille","title":"Provençal Ratatouille","category":"Sides","cuisine":"French","description":"Summer vegetables cooked one by one, then simmered together with tomato, thyme and good olive oil.","prepMin":25,"cookMin":50,"serves":6,"difficulty":"Medium","ingredients":[{"text":"5 Tbsp olive oil, divided, plus more to finish","header":false},{"text":"1 medium eggplant (about 1 lb), cut into ¾-inch cubes","header":false},{"text":"2 medium zucchini, cut into ¾-inch half-moons","header":false},{"text":"1 large onion, diced","header":false},{"text":"1 red and 1 yellow bell pepper, cut into 1-inch pieces","header":false},{"text":"4 cloves garlic, thinly sliced","header":false},{"text":"1 can (28 oz) whole peeled tomatoes, crushed by hand","header":false},{"text":"4 sprigs fresh thyme (or 1 tsp dried)","header":false},{"text":"1 bay leaf","header":false},{"text":"1½ tsp salt, plus more to taste","header":false},{"text":"½ tsp black pepper","header":false},{"text":"¼ cup fresh basil, torn","header":false}],"steps":[{"lead":"Brown the eggplant.","text":"Heat 2 Tbsp of the oil in a wide, heavy pot over medium-high heat. Add the eggplant with a pinch of salt and cook 8–10 minutes, stirring, until golden. Spoon into a bowl.","timer":480,"timerText":"8 min"},{"lead":"Sear the zucchini.","text":"Add 1 Tbsp oil and the zucchini and cook about 5 minutes, until lightly browned but still firm. Add to the eggplant.","timer":300,"timerText":"5 min"},{"lead":"Soften the aromatics.","text":"Add the last 2 Tbsp oil, the onion and the peppers. Cook 8–10 minutes over medium heat until soft, then stir in the garlic for 1 minute.","timer":480,"timerText":"8 min"},{"lead":"Simmer the tomatoes.","text":"Add the tomatoes and their juice, the thyme, bay leaf, salt and pepper. Simmer for 15 minutes, until slightly thickened.","timer":900,"timerText":"15 min"},{"lead":"Bring it together.","text":"Return the eggplant and zucchini to the pot, cover and simmer gently 15–20 minutes, until everything is tender but still holds its shape.","timer":900,"timerText":"15 min"},{"lead":"Finish and serve.","text":"Fish out the bay leaf and thyme stems. Fold in the basil, taste for salt and finish with a thread of olive oil. Serve warm or at room temperature.","timer":0,"timerText":""}],"kitchenNote":"Ratatouille is even better the next day, so make a big pot. Spoon leftovers over polenta or toast, or bake them with eggs cracked right on top.","accent":{"garnish":"herbs","color":"#5E7D3A"},"image":"images/dishes/provencal-ratatouille.jpg","photo":"images/photos/villa.png","tags":["vegan","gluten-free","make-ahead"],"prepText":"25 min","cookText":"50 min","totalText":"1 hr 15 min","garnish":"images/garnish/herbs.png","thumb":"images/dishes/provencal-ratatouille.jpg"},{"id":"irish-soda-bread","title":"Irish Soda Bread","category":"Breads","cuisine":"Irish","description":"A craggy, golden loaf made with just four ingredients and no yeast. From bowl to oven in ten minutes.","prepMin":10,"cookMin":40,"serves":8,"difficulty":"Easy","ingredients":[{"text":"4 cups (500 g) all-purpose flour, plus more for dusting","header":false},{"text":"1 tsp baking soda","header":false},{"text":"1 tsp fine salt","header":false},{"text":"1¾ cups (420 ml) cold buttermilk, plus a splash more if needed","header":false},{"text":"Salted butter, to serve","header":false}],"steps":[{"lead":"Heat the oven.","text":"Preheat the oven to 425°F (220°C) and dust a baking sheet or cast-iron skillet with flour.","timer":0,"timerText":""},{"lead":"Mix the dry ingredients.","text":"Whisk the flour, baking soda and salt together in a large bowl, then make a well in the center.","timer":0,"timerText":""},{"lead":"Add the buttermilk.","text":"Pour in most of the buttermilk and stir with a fork or one cupped hand until a soft, shaggy dough forms. Add the rest only if dry flour remains.","timer":0,"timerText":""},{"lead":"Shape gently.","text":"Turn the dough onto a floured counter and pat it into a round about 2 inches high. Handle it as little as possible to keep the loaf tender.","timer":0,"timerText":""},{"lead":"Score the cross.","text":"Set the round on the sheet and cut a deep cross across the top with a floured knife, almost to the edges, to help it bake through.","timer":0,"timerText":""},{"lead":"Bake.","text":"Bake 35–40 minutes, until deep golden and hollow-sounding when tapped underneath. Cool on a rack, wrapped in a clean tea towel for a softer crust.","timer":2100,"timerText":"35 min"}],"kitchenNote":"Granny always said the cross was there to let the fairies out. It's at its best the day it's baked, still a little warm, with plenty of good salted butter.","accent":{"garnish":"wheat","color":"#C9973F"},"image":"images/dishes/irish-soda-bread.jpg","photo":"images/photos/cottage.png","tags":["vegetarian","quick-bread","four-ingredients"],"prepText":"10 min","cookText":"40 min","totalText":"50 min","garnish":"images/garnish/wheat.png","thumb":"images/dishes/irish-soda-bread.jpg"},{"id":"zaatar-manakish","title":"Za'atar Manakish","category":"Breads","cuisine":"Lebanese","description":"Soft, dimpled Lebanese flatbreads brushed with a fragrant paste of za'atar and olive oil, baked until golden at the edges.","prepMin":95,"cookMin":25,"serves":6,"difficulty":"Medium","ingredients":[{"text":"Dough","header":true},{"text":"3 cups (375 g) all-purpose flour","header":false},{"text":"2¼ tsp (1 packet) instant yeast","header":false},{"text":"1 tsp sugar","header":false},{"text":"1 tsp salt","header":false},{"text":"1 cup (240 ml) lukewarm water","header":false},{"text":"2 Tbsp olive oil, plus more for the bowl","header":false},{"text":"Topping","header":true},{"text":"1/3 cup za'atar spice blend","header":false},{"text":"1/3 cup extra-virgin olive oil","header":false},{"text":"To serve","header":true},{"text":"Sliced cucumber and tomato","header":false},{"text":"Fresh mint leaves","header":false},{"text":"Labneh or thick Greek yogurt","header":false}],"steps":[{"lead":"Mix the dough.","text":"Whisk the flour, yeast, sugar and salt in a large bowl. Add the water and olive oil and knead for 8 minutes, until smooth, soft and elastic.","timer":480,"timerText":"8 min"},{"lead":"Let it rise.","text":"Place the dough in an oiled bowl, cover and leave in a warm spot for 1 hour, until doubled in size.","timer":3600,"timerText":"1 hr"},{"lead":"Heat the oven.","text":"Set a baking steel or upturned sheet pan on the lowest rack and heat the oven to 475°F for at least 30 minutes, so the pan is scorching hot.","timer":1800,"timerText":"30 min"},{"lead":"Shape the rounds.","text":"Divide the dough into 6 pieces, roll into balls and rest for 10 minutes. Press each into a 7-inch round about ¼ inch thick, then dimple all over with your fingertips.","timer":600,"timerText":"10 min"},{"lead":"Add the za'atar.","text":"Stir the za'atar into the olive oil to make a loose paste. Spread a generous spoonful over each round, leaving a thin bare border.","timer":0,"timerText":""},{"lead":"Bake until golden.","text":"Slide two rounds at a time onto the hot pan and bake for 6–8 minutes, until the edges puff and turn golden and the bottoms are spotted brown.","timer":360,"timerText":"6 min"},{"lead":"Roll and eat.","text":"Serve warm, folded around sliced cucumber, tomato, fresh mint and a cool smear of labneh.","timer":0,"timerText":""}],"kitchenNote":"Buy za'atar from a Middle Eastern grocer if you can; it's greener and far more fragrant. Leftover rounds crisp up beautifully in a dry skillet for breakfast.","accent":{"garnish":"olive","color":"#7A7F2E"},"image":"images/dishes/zaatar-manakish.jpg","photo":"images/photos/bazaar.png","tags":["vegetarian","flatbread","yeasted","make-ahead"],"prepText":"1 hr 35 min","cookText":"25 min","totalText":"2 hr","garnish":"images/garnish/olive.png","thumb":"images/dishes/zaatar-manakish.jpg"},{"id":"grandmas-apple-crumble","title":"Grandma's Apple Crumble","category":"Desserts","cuisine":"British","description":"Soft cinnamon apples under a buttery oat crumble, baked until bubbling. Pass the custard.","prepMin":20,"cookMin":45,"serves":6,"difficulty":"Easy","ingredients":[{"text":"For the filling","header":true},{"text":"2½ lb tart apples (about 6), peeled, cored and sliced","header":false},{"text":"¼ cup (50 g) granulated sugar","header":false},{"text":"1 Tbsp lemon juice","header":false},{"text":"1 Tbsp all-purpose flour","header":false},{"text":"1 tsp ground cinnamon","header":false},{"text":"For the crumble","header":true},{"text":"1¼ cups (160 g) all-purpose flour","header":false},{"text":"½ cup (100 g) light brown sugar","header":false},{"text":"½ cup (45 g) rolled oats","header":false},{"text":"½ tsp ground cinnamon","header":false},{"text":"¼ tsp salt","header":false},{"text":"½ cup (1 stick) cold unsalted butter, cubed","header":false},{"text":"Custard, cream or vanilla ice cream, to serve","header":false}],"steps":[{"lead":"Heat the oven.","text":"Preheat the oven to 375°F (190°C) and butter a 2-quart baking dish.","timer":0,"timerText":""},{"lead":"Toss the apples.","text":"In a large bowl, toss the apple slices with the sugar, lemon juice, flour and cinnamon. Tip into the dish and spread them out evenly.","timer":0,"timerText":""},{"lead":"Rub the crumble.","text":"Mix the flour, brown sugar, oats, cinnamon and salt. Rub in the cold butter with your fingertips until the mixture clumps like damp sand with a few larger pebbles.","timer":0,"timerText":""},{"lead":"Top the fruit.","text":"Scatter the crumble loosely over the apples, right to the edges. Don't press it down; the little gaps let it crisp.","timer":0,"timerText":""},{"lead":"Bake.","text":"Bake 40–45 minutes, until the top is deep golden and the juices bubble thickly at the edges.","timer":2400,"timerText":"40 min"},{"lead":"Rest and serve.","text":"Let it settle for 10 minutes, then spoon into bowls with warm custard, cold cream or a scoop of vanilla ice cream.","timer":600,"timerText":"10 min"}],"kitchenNote":"Use a mix of apples if you can, some sharp and some sweet. A handful of blackberries tucked in with the apples was always Grandma's late-summer secret.","accent":{"garnish":"apple","color":"#A8322A"},"image":"images/dishes/grandmas-apple-crumble.jpg","photo":"images/photos/cottage.png","tags":["vegetarian","baking","family"],"prepText":"20 min","cookText":"45 min","totalText":"1 hr 5 min","garnish":"images/garnish/apple.png","thumb":"images/dishes/grandmas-apple-crumble.jpg"},{"id":"mango-sticky-rice","title":"Mango Sticky Rice","category":"Desserts","cuisine":"Thai","description":"Chewy sticky rice soaked in sweet, salty coconut milk, served with ripe mango and a sprinkle of toasted sesame.","prepMin":255,"cookMin":30,"serves":4,"difficulty":"Medium","ingredients":[{"text":"1½ cups (300 g) Thai glutinous (sticky) rice","header":false},{"text":"1 can (13½ oz) full-fat coconut milk, divided","header":false},{"text":"½ cup (100 g) sugar","header":false},{"text":"¾ tsp salt, divided","header":false},{"text":"1 tsp rice flour or cornstarch","header":false},{"text":"2 ripe mangoes (Ataulfo or Nam Dok Mai)","header":false},{"text":"1 Tbsp toasted sesame seeds","header":false}],"steps":[{"lead":"Soak the rice.","text":"Rinse the rice in several changes of cool water until it runs almost clear. Cover with fresh water and soak for at least 4 hours, or overnight.","timer":14400,"timerText":"4 hr"},{"lead":"Steam the rice.","text":"Drain well and spread in a steamer basket lined with damp cheesecloth. Cover and steam over simmering water for 20–25 minutes, flipping halfway, until glossy and tender.","timer":1200,"timerText":"20 min"},{"lead":"Sweeten the coconut.","text":"Meanwhile, warm 1 cup of the coconut milk with the sugar and ½ tsp salt over medium-low heat, stirring until dissolved. Don't let it boil.","timer":0,"timerText":""},{"lead":"Let it soak in.","text":"Tip the hot rice into a bowl, pour over the sweet coconut milk and stir gently. Cover and let stand for 20 minutes while the rice drinks it up.","timer":1200,"timerText":"20 min"},{"lead":"Make the topping.","text":"Whisk the remaining coconut milk with ¼ tsp salt and the rice flour. Simmer for 1–2 minutes, stirring, until lightly thickened.","timer":60,"timerText":"1 min"},{"lead":"Slice and serve.","text":"Peel the mangoes and slice the cheeks off the stone. Mound the rice beside the mango, spoon the salty coconut sauce over and sprinkle with sesame.","timer":0,"timerText":""}],"kitchenNote":"Only Thai sticky rice works here; ordinary rice won't turn chewy. Pick mangoes that smell sweet at the stem and give a little when you press them.","accent":{"garnish":"mango","color":"#E39A1E"},"image":"images/dishes/mango-sticky-rice.jpg","photo":"images/photos/teahouse.png","tags":["vegan","gluten-free","coconut","summer"],"prepText":"4 hr 15 min","cookText":"30 min","totalText":"4 hr 45 min","garnish":"images/garnish/mango.png","thumb":"images/dishes/mango-sticky-rice.jpg"},{"id":"masala-chai","title":"Masala Chai","category":"Drinks","cuisine":"Indian","description":"Strong black tea simmered with milk, fresh ginger and whole warm spices. Comfort in a cup.","prepMin":5,"cookMin":12,"serves":2,"difficulty":"Easy","ingredients":[{"text":"1½ cups water","header":false},{"text":"1 cup whole milk","header":false},{"text":"2 tsp loose Assam tea, or 2 black tea bags","header":false},{"text":"2–3 tsp sugar, to taste","header":false},{"text":"4 green cardamom pods","header":false},{"text":"1 cinnamon stick (about 2 inches)","header":false},{"text":"4 whole cloves","header":false},{"text":"4 black peppercorns","header":false},{"text":"1-inch piece fresh ginger, thinly sliced","header":false}],"steps":[{"lead":"Crack the spices.","text":"Lightly crush the cardamom, cinnamon, cloves and peppercorns in a mortar, or under the flat of a knife, just to open them up.","timer":0,"timerText":""},{"lead":"Simmer the spices.","text":"Bring the water, crushed spices and ginger to a boil in a small saucepan, then simmer for 3–4 minutes until fragrant and golden.","timer":180,"timerText":"3 min"},{"lead":"Brew the tea.","text":"Add the tea and simmer for 2 minutes, until the liquid turns a deep reddish brown.","timer":120,"timerText":"2 min"},{"lead":"Add milk and sugar.","text":"Pour in the milk and sugar and bring back up until the chai rises in the pan. Lower the heat and let it rise once more, about 2 minutes in all.","timer":120,"timerText":"2 min"},{"lead":"Strain and serve.","text":"Strain into warmed cups and serve right away, piping hot.","timer":0,"timerText":""}],"kitchenNote":"Letting the chai rise twice is the old trick for a rich, rounded cup. Watch the pan closely, because milk boils over the very second you look away!","accent":{"garnish":"spice","color":"#8A4B22"},"image":"images/dishes/masala-chai.jpg","photo":"images/photos/bazaar.png","tags":["vegetarian","gluten-free","warming"],"prepText":"5 min","cookText":"12 min","totalText":"17 min","garnish":"images/garnish/spice.png","thumb":"images/dishes/masala-chai.jpg"},{"id":"moroccan-mint-tea","title":"Moroccan Mint Tea","category":"Drinks","cuisine":"Moroccan","description":"Green tea steeped with a fistful of fresh spearmint and sweetened generously, then poured from a height so every glass wears a little foam.","prepMin":5,"cookMin":10,"serves":4,"difficulty":"Easy","ingredients":[{"text":"1 Tbsp Chinese gunpowder green tea","header":false},{"text":"4 cups (1 L) boiling water, divided","header":false},{"text":"1 large bunch fresh spearmint (about 1 oz)","header":false},{"text":"3–4 Tbsp sugar, to taste","header":false}],"steps":[{"lead":"Warm the pot.","text":"Swirl a splash of boiling water around a heatproof teapot to warm it, then pour it out.","timer":0,"timerText":""},{"lead":"Save the spirit.","text":"Add the tea and 1 cup of the boiling water. Steep for 1 minute, then pour this first glass off and set it aside; it holds the tea's best flavour.","timer":60,"timerText":"1 min"},{"lead":"Wash the leaves.","text":"Pour ½ cup boiling water over the leaves, swirl for a few seconds and discard it. This rinse tames the bitterness.","timer":0,"timerText":""},{"lead":"Add the mint and sugar.","text":"Push the mint into the pot, add the sugar and the reserved first glass, then fill with the remaining 2½ cups boiling water. Steep for 3–4 minutes.","timer":180,"timerText":"3 min"},{"lead":"Mix by pouring.","text":"Pour out a glass and tip it back into the pot two or three times to dissolve the sugar. Taste, and add more sugar if you like it sweeter.","timer":0,"timerText":""},{"lead":"Pour from a height.","text":"Lift the pot as you pour into small glasses so each one gets a crown of foam. Serve straight away, with a sprig of mint.","timer":0,"timerText":""}],"kitchenNote":"Spearmint is the one to use, not peppermint. Practise the high pour over the sink: start low, then lift slowly as the glass fills.","accent":{"garnish":"mint","color":"#3E8E5A"},"image":"images/dishes/moroccan-mint-tea.jpg","photo":"images/photos/bazaar.png","tags":["vegan","gluten-free","tea","hospitality"],"prepText":"5 min","cookText":"10 min","totalText":"15 min","garnish":"images/garnish/mint.png","thumb":"images/dishes/moroccan-mint-tea.jpg"}]},"layout":{"_comment":"Shared 1920x1080 layout. Roku (roku/data/layout.json) and web (web/recipes.js) both read this; tools/make_art.py bakes panels at these coordinates. Title-safe area is x 96..1824, y 54..1026.","screen":{"w":1920,"h":1080,"safe":[96,54,1824,1026]},"colors":{"gold":"0xD9A94AFF","goldLight":"0xF2D592FF","ink":"0x2E1C10FF","inkSoft":"0x5A3D24FF","rust":"0x7A3B16FF","dim":"0x0A0604C8","white":"0xFFFFFFFF"},"fonts":{"script":"PinyonScript-Regular.ttf","serif":"CrimsonText-Regular.ttf","serifBold":"CrimsonText-Bold.ttf","hand":"Kalam-Regular.ttf"},"home":{"bg":"images/ui/home_bg.jpg","title":{"x":160,"y":48,"w":1600,"size":118},"tagline":{"x":160,"y":188,"w":1600,"size":28},"rows":{"x":120,"y":270,"h":756,"rowH":378,"labelSize":54,"labelH":64},"card":{"w":360,"h":300,"gap":40,"thumbH":184,"visible":4,"titleSize":28,"metaSize":26,"focusScale":1.05},"peek":{"fade":"images/ui/fade_r.png","fadeX":-10,"fadeW":114}},"recipe":{"bg":"images/ui/recipe_bg.jpg","header":{"x":560,"y":46,"w":800,"size":58},"dish":{"x":104,"y":128,"w":608,"h":404},"ingCard":{"x":96,"y":548,"w":624,"h":478},"ingHeader":{"x":214,"y":556,"w":480,"size":58},"ingList":{"x":128,"y":650,"w":566,"h":356,"size":28,"gap":10,"box":28,"textX":44},"garnishSmall":{"x":100,"y":538,"s":116},"titleCard":{"x":744,"y":128,"w":1050,"h":330},"title":{"x":790,"y":142,"w":840,"h":104,"size":78,"sizeLong":62,"longAt":24},"desc":{"x":792,"y":250,"w":956,"size":28},"meta":{"x":788,"y":344,"colW":240,"icon":46,"size":27},"garnish":{"x":1612,"y":60,"s":212},"dirHeader":{"x":770,"y":464,"w":600,"size":62},"steps":{"x":764,"y":558,"w":1050,"h":290,"size":28,"gap":14,"ring":54,"textX":74},"noteCard":{"x":744,"y":864,"w":840,"h":162},"noteHeader":{"x":790,"y":860,"w":600,"size":46},"note":{"x":790,"y":922,"w":766,"size":26,"maxLines":3},"photo":{"x":1600,"y":836,"w":224,"h":190}},"cook":{"bg":"images/ui/cook_bg.jpg","sheet":{"x":150,"y":96,"w":1620,"h":888},"title":{"x":260,"y":118,"w":1400,"size":66},"counter":{"x":260,"y":218,"w":1400,"size":32},"ring":{"x":900,"y":272,"s":120,"size":64},"lead":{"x":260,"y":412,"w":1400,"size":58},"text":{"x":300,"y":494,"w":1320,"size":44,"maxLines":6},"timer":{"y":798,"size":34,"icon":40,"gap":14},"dots":{"y":874,"s":22,"gap":18},"hint":{"x":260,"y":912,"w":1400,"size":27}},"menu":{"panel":{"x":600,"y":120,"w":720,"h":840},"title":{"x":640,"y":140,"w":640,"size":60},"list":{"x":660,"y":236,"w":600,"itemH":58,"visible":11,"size":32}}}};
